import ast,base64,difflib,hashlib,json
p=json.loads(base64.b64decode(''))
checks=[];files={};diffs={}
def ck(n,v):
 assert v,n
 checks.append(n)
def definitions(src,t):
 return {n.name:ast.get_source_segment(src,n) for n in t.body if isinstance(n,(ast.FunctionDef,ast.ClassDef))}
def assignments(src,t):
 return {n.targets[0].id:ast.get_source_segment(src,n.value) for n in t.body if isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name)}
allowed={'sender.py':['ACTUAL_INPUTS_READY','FILES'],'receiver.py':['ACTUAL_INPUTS_READY','FILES'],'relay.py':['ACTUAL_INPUTS_READY','FILES','HELPERS'],'inert.py':['PINS']}
for name,pair in p['pairs'].items():
 old,new=pair['before'],pair['after'];ot,nt=ast.parse(old),ast.parse(new)
 compile(ot,name+'-before','exec');compile(nt,name+'-after','exec')
 of,nf=definitions(old,ot),definitions(new,nt)
 ck(name+':all_definitions_byte_exact',of==nf)
 oa,na=assignments(old,ot),assignments(new,nt)
 changed=[n for n in oa if oa[n]!=na.get(n)]
 ck(name+':only_declared_top_bindings',changed==allowed[name] and set(oa)==set(na))
 def filtered(t):
  return [ast.dump(n,include_attributes=False) for n in t.body if not(isinstance(n,ast.Assign) and len(n.targets)==1 and isinstance(n.targets[0],ast.Name) and n.targets[0].id in allowed[name])]
 ck(name+':all_other_ast_identical',filtered(ot)==filtered(nt))
 if name!='inert.py':
  ck(name+':actual_two_source_rows',ast.literal_eval(na['FILES'])==p['source_metadata'])
  ck(name+':ready_literal_true',ast.literal_eval(na['ACTUAL_INPUTS_READY']) is True)
  ck(name+':original_deadline',na['UNTIL']==oa['UNTIL'])
 if name=='relay.py':ck('relay:final_helper_pins',ast.literal_eval(na['HELPERS'])==p['helperPins'])
 if name=='inert.py':ck('inert:final_source_pins',ast.literal_eval(na['PINS'])==p['pins'])
 raw=new.encode();files[name]={'bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'unchanged_definitions':list(nf),'changed_assignments':changed}
 diffs[name]=''.join(difflib.unified_diff(old.splitlines(True),new.splitlines(True),fromfile='before/'+name,tofile='after/'+name))
for name in ['sender.py','receiver.py','relay.py']:
 ck(name+':size_hash_matches_inert_pin',p['pins'][name]==[files[name]['bytes'],files[name]['sha256']])
for name in ['sender.py','receiver.py']:
 ck(name+':hash_matches_relay_pin',p['helperPins'][name]==files[name]['sha256'])
print(json.dumps({'schema':'heptabao.source-carrier-two-actual-inputs-root-ast-verification.r1','checks':checks,'checks_passed':len(checks),'files':files,'diffs':diffs,'compiled_modules':8,'executed_modules':0,'actual_host_access':False,'network_calls':0,'business_dispatch':False,'original81_archive_pending':True},indent=2,sort_keys=True))
